	me.skinTimerEvent=function() {
		if (player.isInVR()) return;
		me.ggCurrentTime=new Date().getTime();
		me._button_image_up.ggUpdateConditionTimer();
		me._button_image_down.ggUpdateConditionTimer();
		me._button_image_left.ggUpdateConditionTimer();
		me._button_image_right.ggUpdateConditionTimer();
		me._svgsubmenupdf.ggUpdateConditionTimer();
		me._cnt_submenu_1.ggUpdateConditionTimer();
		me._svgorderonline.ggUpdateConditionTimer();
		me._cnt_submenu.ggUpdateConditionTimer();
		if (me._gallery_fx.ggLastIsActive!=me._gallery_fx.ggIsActive()) {
			me._gallery_fx.ggLastIsActive=me._gallery_fx.ggIsActive();
			if (me._gallery_fx.ggLastIsActive) {
				if (player.transitionsDisabled) {
					me._gallery_picture.style.transition='none';
				} else {
					me._gallery_picture.style.transition='all 500ms ease-out 0ms';
				}
				me._gallery_picture.style.opacity='0';
				me._gallery_picture.style.visibility='hidden';
				me._gallery_picture.ggSubElement.src='';
			} else {
				if (player.transitionsDisabled) {
					me._gallery_picture.style.transition='none';
				} else {
					me._gallery_picture.style.transition='all 500ms ease-out 0ms';
				}
				me._gallery_picture.style.opacity='1';
				me._gallery_picture.style.visibility=me._gallery_picture.ggVisible?'inherit':'hidden';
				me._gallery_picture.ggSubElement.src=me._gallery_picture.ggText;
			}
		}
		if (me._timer_hotspotani.ggLastIsActive!=me._timer_hotspotani.ggIsActive()) {
			me._timer_hotspotani.ggLastIsActive=me._timer_hotspotani.ggIsActive();
			if (me._timer_hotspotani.ggLastIsActive) {
				player.setVariableValue('ht_ani', !player.getVariableValue('ht_ani'));
			} else {
				var list=me.findElements("Rect_HotAnim1",true);
				while(list.length>0) {
					var e=list.pop();
					var flag=e.ggScaleActive;
					if (player.transitionsDisabled) {
						e.style.transition='none';
					} else {
						e.style.transition='all 64ms ease-out 0ms';
					}
					if (flag) {
						e.ggParameter.sx=1;e.ggParameter.sy=1;
					} else {
						e.ggParameter.sx=1;e.ggParameter.sy=1;
					}
					e.ggScaleActive=!flag;
						e.style.transform=parameterToTransform(e.ggParameter);
					setTimeout(function() {skin.updateSize(e);}, 114);
				}
				var list=me.findElements("Rect_HotAnim1",true);
				while(list.length>0) {
					var e=list.pop();
					var flag=e.ggOpacitiyActive;
					if (player.transitionsDisabled) {
						e.style.transition='none';
					} else {
						e.style.transition='all 500ms ease-out 0ms';
					}
					if (flag) {
						e.style.opacity='0.1';
						e.style.visibility=e.ggVisible?'inherit':'hidden';
					} else {
						e.style.opacity='1';
						e.style.visibility=e.ggVisible?'inherit':'hidden';
					}
					e.ggOpacitiyActive=!flag;
				}
			}
		}
		me._cnt_submenu_timer.ggUpdateConditionTimer();
		if (me._cnt_submenu_timer.ggLastIsActive!=me._cnt_submenu_timer.ggIsActive()) {
			me._cnt_submenu_timer.ggLastIsActive=me._cnt_submenu_timer.ggIsActive();
			if (me._cnt_submenu_timer.ggLastIsActive) {
			} else {
				player.setVariableValue('cnt_Submenu', false);
			}
		}
		me._screen_captured_popup_timer.ggUpdateConditionTimer();
		me._cnt_submenu_timer_pdf.ggUpdateConditionTimer();
		if (me._cnt_submenu_timer_pdf.ggLastIsActive!=me._cnt_submenu_timer_pdf.ggIsActive()) {
			me._cnt_submenu_timer_pdf.ggLastIsActive=me._cnt_submenu_timer_pdf.ggIsActive();
			if (me._cnt_submenu_timer_pdf.ggLastIsActive) {
			} else {
				player.setVariableValue('cnt_Submenu_PDF', false);
			}
		}
		var hs='';
		if (me._loadingbar.ggParameter) {
			hs+=parameterToTransform(me._loadingbar.ggParameter) + ' ';
		}
		hs+='scale(' + (1 * player.getPercentLoaded() + 0) + ',1.0) ';
		me._loadingbar.style.transform=hs;
		if (!player.getLockedKeyboard()) {
			switch(me.skinKeyPressedText) {
				case 'ArrowLeft':
					if (
	(
		((player.getVariableValue('ScreenBg') == false)) && 
		((player.getVariableValue('CurrentWindow') != "Help"))
	)
) {
	player.changePanLog(1,true);
}
					break;
				case 'ArrowRight':
					if (
	(
		((player.getVariableValue('ScreenBg') == false)) && 
		((player.getVariableValue('CurrentWindow') != "Help"))
	)
) {
	player.changePanLog(-1,true);
}
					break;
			}
			switch(me.skinKeyPressedKey) {
				case 38:
					if (
	(
		((player.getVariableValue('ScreenBg') == false)) && 
		((player.getVariableValue('CurrentWindow') != "Help"))
	)
) {
	player.changeTiltLog(1,true);
}
					break;
				case 40:
					if (
	(
		((player.getVariableValue('ScreenBg') == false)) && 
		((player.getVariableValue('CurrentWindow') != "Help"))
	)
) {
	player.changeTiltLog(-1,true);
}
					break;
			}
		}
		for (const id in hotspotTemplates) {
			const tmpl=hotspotTemplates[id];
			tmpl.forEach(function(hotspot) {
				if (hotspot.hotspotTimerEvent) {
					hotspot.hotspotTimerEvent();
				}
			});
		};
	};
